<script lang="ts">import FieldRoot from'@fex-design/svelte/primitive/field';import FieldControl from'@fex-design/svelte/primitive/field-control';import FieldError from'@fex-design/svelte/primitive/field-error';import FieldLabel from'@fex-design/svelte/primitive/field-label';import Button from'@fex-design/svelte/ui/button';import{regionOptions}from'./data';import DemoCascader from'./demo-cascader.svelte';import Demo from'./demo-section.svelte';let value=$state<unknown[]>([]),invalid=$state(false)</script><Demo title="Form validation" description="Submit empty to verify Field ARIA and Cascader error styling."><form class="space-y-space-md" onsubmit={event=>{event.preventDefault();invalid=!value.length}}><FieldRoot required {invalid} hasError={invalid}><FieldLabel>所在地区</FieldLabel><FieldControl>{#snippet children(binding)}<DemoCascader options={regionOptions} value={value as string[]} status={invalid?'error':undefined} triggerProps={binding.props} onChange={next=>{value=(next??[])as unknown[];invalid=false}}/>{/snippet}</FieldControl>{#if invalid}<FieldError>{#snippet children()}请选择所在地区{/snippet}</FieldError>{/if}</FieldRoot><Button type="submit">提交校验</Button></form></Demo>
